#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <algorithm>
#include <climits>
using namespace nvcuda;

__global__ void conv2d_3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    long long total) {
  // Tensor-core (WMMA) implicit-GEMM formulation. Each block computes a
  // 32 (output channel) x 224 (output pixel) tile for one image and one
  // output row. The 3x3xC_in(=3) reduction (K=27) is zero-padded to
  // K=32 and accumulated in fp32 via bf16 MMA fragments. The wider
  // output tile halves the number of blocks that restage the same
  // weight tile and gives each warp two adjacent 16x16 output tiles.
  constexpr int M_TILE = 32;   // output channels per block
  constexpr int N_TILE = 224;  // output pixels per block (single row; covers W_out=222 in one tile)
  constexpr int K_TILE = 32;   // padded reduction extent (27 -> 32)
  constexpr int A_STRIDE = K_TILE + 8;  // skewed smem leading dims reduce WMMA bank conflicts
  constexpr int B_STRIDE = N_TILE + 8;
  constexpr int C_STRIDE = N_TILE + 4;  // fp32 accumulator staging stride
  __shared__ __align__(32) __nv_bfloat16 s_a[M_TILE * A_STRIDE];
  __shared__ __align__(32) __nv_bfloat16 s_b[K_TILE * B_STRIDE];   // (K_TILE, N_TILE) im2col tile, padded stride
  __shared__ __align__(32) float           s_c[M_TILE * C_STRIDE]; // fp32 accumulator staging, padded stride
  const int co_tiles = (C_out + M_TILE - 1) / M_TILE;
  const int co0 = (blockIdx.z % co_tiles) * M_TILE;
  const int n   = blockIdx.z / co_tiles;
  const int oh  = blockIdx.y;
  const int ow0 = blockIdx.x * N_TILE;
  const int tid = threadIdx.x;
  // Stage the weight tile [M_TILE x K_TILE] (row-major), zero-padding
  // the K dimension from 27 to 32 and any out-of-range output channels.
  for (int i = tid; i < M_TILE * K_TILE; i += blockDim.x) {
    int co = i / K_TILE;
    int k  = i % K_TILE;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (co0 + co < C_out && k < 27) {
      v = w[(long long)(co0 + co) * C_in * 9 + k];
    }
    s_a[co * A_STRIDE + k] = v;
  }
  // Stage the im2col input tile [K_TILE x N_TILE] (row-major). Element
  // (k, j) holds x[n, ci, oh+kh, ow0+j+kw] with k = ci*9 + kh*3 + kw.
  // Rows 27..31 stay zero so the padding contributes nothing. Consecutive
  // threads read consecutive input columns, keeping the loads coalesced.
  for (int i = tid; i < K_TILE * N_TILE; i += blockDim.x) {
    int k = i / N_TILE;
    int j = i % N_TILE;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (k < 27) {
      int ci = k / 9;
      int kh = (k % 9) / 3;
      int kw = k % 3;
      int ih = oh + kh;
      int iw = ow0 + j + kw;
      if (iw < W_in) {
        v = x[(((long long)n * C_in + ci) * H_in + ih) * W_in + iw];
      }
    }
    s_b[k * B_STRIDE + j] = v;
  }
  __syncthreads();
  // 14 warps arranged 2 (M) x 7 (N), each owning one 16x32 WMMA pair.
  const int warp = tid >> 5;
  const int wm = warp & 1;
  const int wn = warp >> 1;
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc0;
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc1;
  wmma::fill_fragment(acc0, 0.0f);
  wmma::fill_fragment(acc1, 0.0f);
  #pragma unroll
  for (int k0 = 0; k0 < K_TILE; k0 += 16) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b_frag0;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b_frag1;
    wmma::load_matrix_sync(a_frag, s_a + wm * 16 * A_STRIDE + k0, A_STRIDE);
    wmma::load_matrix_sync(b_frag0, s_b + k0 * B_STRIDE + wn * 32, B_STRIDE);
    wmma::load_matrix_sync(b_frag1, s_b + k0 * B_STRIDE + wn * 32 + 16, B_STRIDE);
    wmma::mma_sync(acc0, a_frag, b_frag0, acc0);
    wmma::mma_sync(acc1, a_frag, b_frag1, acc1);
  }
  // Drain the fp32 accumulators through shared memory, then convert to
  // bf16 and issue streaming (write-through, L2-bypassing) global stores.
  // The output tensor (~314MB) is written exactly once and never re-read,
  // so keeping it out of L2 preserves cache for the reused input/weight
  // tiles and raises effective output-store bandwidth.
  wmma::store_matrix_sync(s_c + wm * 16 * C_STRIDE + wn * 32, acc0, C_STRIDE,
                          wmma::mem_row_major);
  wmma::store_matrix_sync(s_c + wm * 16 * C_STRIDE + wn * 32 + 16, acc1, C_STRIDE,
                          wmma::mem_row_major);
  __syncthreads();
  for (int i = tid; i < M_TILE * N_TILE; i += blockDim.x) {
    int co = i / N_TILE;
    int j  = i % N_TILE;
    int ow = ow0 + j;
    if (co0 + co < C_out && ow < W_out) {
      long long out = (((long long)n * C_out + co0 + co) * H_out + oh) * W_out + ow;
      __stwt(&y[out], __float2bfloat16(s_c[co * C_STRIDE + j]));
    }
  }
}

at::Tensor conv2d_bf16_forward(at::Tensor x, at::Tensor w) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16 && w.scalar_type() == at::kBFloat16,
              "x and w must be bfloat16");
  TORCH_CHECK(x.dim() == 4 && w.dim() == 4, "x and w must be 4D");

  auto xc = x.contiguous();
  auto wc = w.contiguous();

  int64_t N = xc.size(0);
  int64_t C_in = xc.size(1);
  int64_t H_in = xc.size(2);
  int64_t W_in = xc.size(3);
  int64_t C_out = wc.size(0);

  TORCH_CHECK(wc.size(1) == C_in, "weight/input channel mismatch");
  TORCH_CHECK(C_in == 3, "this kernel is specialized for C_in == 3");
  TORCH_CHECK(wc.size(2) == 3 && wc.size(3) == 3, "kernel size must be 3x3");
  TORCH_CHECK(H_in >= 3 && W_in >= 3, "input must be at least 3x3");
  TORCH_CHECK(N <= INT_MAX && C_in <= INT_MAX && H_in <= INT_MAX && W_in <= INT_MAX &&
              C_out <= INT_MAX, "tensor too large");

  int64_t H_out = H_in - 2;
  int64_t W_out = W_in - 2;
  auto y = at::empty({N, C_out, H_out, W_out}, xc.options());

  long long total = (long long)N * C_out * H_out * W_out;
  if (total == 0) {
    return y;
  }

  const __nv_bfloat16* xp = reinterpret_cast<const __nv_bfloat16*>(xc.data_ptr<at::BFloat16>());
  const __nv_bfloat16* wp = reinterpret_cast<const __nv_bfloat16*>(wc.data_ptr<at::BFloat16>());
  __nv_bfloat16* yp = reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>());

  const int M_TILE = 32;
  const int N_TILE = 224;
  dim3 threads(448);
  int tiles_n = (int)((W_out + N_TILE - 1) / N_TILE);
  int co_tiles = (int)((C_out + M_TILE - 1) / M_TILE);
  dim3 blocks(tiles_n, (int)H_out, (int)(N * co_tiles));
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  conv2d_3x3_bf16_kernel<<<blocks, threads, 0, stream>>>(
      xp, wp, yp,
      (int)N, (int)C_in, (int)H_in, (int)W_in,
      (int)C_out, (int)H_out, (int)W_out,
      total);
  TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");

  return y;
}
'''

